select (select count(*) from public.recipes where slug in ('blue-bottle-hario-bottle-cold-brew-68g-750g')) as batch_recipes,(select count(*) from public.roasters where slug in ('caffeine-lab','emirati-coffee')) as new_roasters,(select count(*) from public.recipe_steps s join public.recipes r on r.id=s.recipe_id where r.slug in ('blue-bottle-hario-bottle-cold-brew-68g-750g')) as steps,(select count(*) from public.recipe_pours p join public.recipes r on r.id=p.recipe_id where r.slug in ('blue-bottle-hario-bottle-cold-brew-68g-750g')) as pours;
